#!/usr/bin/env node
/**
 * Runs only after a verified generated-refresh branch has attempted to merge
 * current main. Resolve ONLY approved generated file conflicts. Preserve manual
 * editorial facts and never treat HTTP response evidence as inventory proof.
 * All results still pass the existing protected canonical validation and Merge Gate.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const LEDGER = 'ops/editorial/event-ticketing-verification-ledger.json';
const TICKETMASTER = 'src/data/generated/ticketmaster-events.json';
const TPWD = 'src/data/generated/tpwd-events.json';
const QUEUE = 'ops/editorial/ticketmaster-authority-candidates.json';
const EVENTS = 'src/data/generated/texas-events.ts';
const ALLOWED = new Set([LEDGER, TICKETMASTER, TPWD, QUEUE, EVENTS]);

export function time(value) {
  const date = typeof value === 'string' ? Date.parse(value) : NaN;
  if (!Number.isFinite(date) || !/^20\d{2}-\d{2}-\d{2}T/.test(value)) {
    throw new Error('Generated refresh is missing a valid ISO source timestamp');
  }
  return date;
}

export function chooseByTimestamp(ours, theirs, key) {
  return time(ours[key]) > time(theirs[key]) ? 'ours' : 'theirs';
}

export function mergeTicketProbeLedger(ours, theirs) {
  if (!Array.isArray(theirs.events) || theirs.events.length !== 12 || !Array.isArray(ours.events) || ours.events.length !== 12
    || !theirs.statewide || !ours.statewide) {
    throw new Error('Both sides must retain the 12-event editorial ledger');
  }
  const merged = structuredClone(theirs);
  const history = { ...(theirs.statewide.ticketLinkProbes ?? {}) };
  const recent = ours.statewide.ticketLinkProbes ?? {};
  for (const [id, row] of Object.entries(recent)) {
    if (row?.eventId !== id || typeof row?.checkedAt !== 'string') throw new Error('Invalid event probe identity');
    const candidateTime = time(row.checkedAt);
    const existingTime = history[id] ? time(history[id].checkedAt) : -Infinity;
    if (candidateTime > existingTime) history[id] = row;
  }
  const theirsRun = theirs.statewide.ticketLinkProbeLatestRun;
  const oursRun = ours.statewide.ticketLinkProbeLatestRun;
  const newest = !theirsRun ? 'ours' : !oursRun ? 'theirs'
    : chooseByTimestamp(oursRun, theirsRun, 'checkedAt');
  const latest = newest === 'ours' ? ours : theirs;
  merged.statewide.ticketLinkProbes = history;
  if (latest.statewide.ticketLinkProbeLatestRun) {
    merged.statewide.ticketLinkProbeLatestRun = latest.statewide.ticketLinkProbeLatestRun;
    merged.statewide.ticketLinkProbeCursor = latest.statewide.ticketLinkProbeCursor;
  }
  // All other source-verified fields belong to current main, not the bot.
  return merged;
}

const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trimEnd();
const fromCommit = (ref, path) => git('show', ref + ':' + path);
const fromStage = (stage, path) => git('show', ':' + stage + ':' + path);
const json = value => JSON.parse(value);

export function validateConflicts(paths) {
  if (!paths.length || paths.some(path => !ALLOWED.has(path))) {
    throw new Error('Unsafe or unexpected merge conflict; preserve current main');
  }
}

function reconcile() {
  const conflicts = git('diff', '--name-only', '--diff-filter=U').split('\n').filter(Boolean);
  validateConflicts(conflicts);
  const oursTicketmaster = json(fromCommit('HEAD', TICKETMASTER));
  const mainTicketmaster = json(fromCommit('origin/main', TICKETMASTER));
  const primary = chooseByTimestamp(oursTicketmaster, mainTicketmaster, 'fetchedAt');
  for (const path of conflicts) {
    if (path === LEDGER) {
      const merged = mergeTicketProbeLedger(json(fromStage(2, LEDGER)), json(fromStage(3, LEDGER)));
      writeFileSync(LEDGER, JSON.stringify(merged, null, 2) + '\n', 'utf8');
    } else {
      let selected = primary;
      if (path === TPWD) {
        selected = chooseByTimestamp(json(fromStage(2, TPWD)), json(fromStage(3, TPWD)), 'generatedAt');
      } else if (path === EVENTS) {
        for (const source of [fromStage(2, EVENTS), fromStage(3, EVENTS)]) {
          if (!source.includes('AUTO-GENERATED by scripts/events/sync-texas-events-safe.mjs.')
            || !source.includes('export const generatedTexasEvents = [')) throw new Error('Unexpected generated calendar content');
        }
      } else if (path === QUEUE) {
        // The authority queue must track the SAME Ticketmaster snapshot.
        for (const source of [json(fromStage(2, QUEUE)), json(fromStage(3, QUEUE))]) time(source.fetchedAt);
      }
      git('checkout', '--' + selected, '--', path);
    }
    git('add', '--', path);
  }
  const remaining = git('diff', '--name-only', '--diff-filter=U');
  if (remaining) throw new Error('Unresolved generated merge conflicts: ' + remaining);
  console.log('Reconciled governed generated conflicts: ' + conflicts.join(', ')
    + '. Ticketmaster source: ' + primary + '; editorial verification preserved from current main.');
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try { reconcile(); }
  catch (error) { console.error('Protected event refresh reconciliation refused: ' + error.message); process.exitCode = 1; }
}
